def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    op = [h[1] for h in history]
    me = [h[0] for h in history]
    op_c = op.count('C')
    op_d = n - op_c

    # Endgame: exploit known cooperators, avoid being sucker-punched
    remaining = 100 - n
    if remaining <= 1:
        if op_d * 4 <= n:
            return 'D'
        return 'D' if op[-1] == 'D' else 'C'
    if remaining <= 3:
        if op_d * 3 <= n:
            return 'D'
        if op_d * 2 >= n:
            return 'D'
        return 'C' if op[-1] == 'C' else 'D'
    if remaining <= 6:
        if op_d * 5 <= n:
            return 'D'
        if op_d * 2 >= n:
            return 'D'
        if op[-1] == 'D':
            return 'D'
        return 'C'

    # Hard classification early
    if n >= 4:
        if op_c == 0:
            return 'D'
        if op_d == 0:
            if remaining <= 15:
                return 'D'
            return 'C'

    # Always-defect detection with tolerance for one noisy C
    if n >= 12 and op_c <= 1:
        return 'D'
    # Always-cooperate detection
    if n >= 10 and op_d == 0:
        if remaining <= 25:
            return 'D' if rng.random() < 0.7 else 'C'
        if n % 9 == 0:
            return 'D'
        return 'C'

    last_op = op[-1]
    last_me = me[-1]

    # Count trailing opponent defection streak
    d_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            d_streak += 1
        else:
            break
    c_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            c_streak += 1
        else:
            break

    # Recently hostile opponent: carry out proportional retaliation, then probe forgiveness
    recent = op[-10:] if n >= 10 else op
    recent_d = recent.count('D')
    recent_c = len(recent) - recent_d

    # Strongly hostile: defect
    if n >= 15 and recent_d * 3 >= len(recent) * 2:
        return 'D'

    # Moderately hostile: punish recent defection
    if last_op == 'D':
        if d_streak >= 3:
            # try occasional reconciliation to break deadlock
            if rng.random() < 0.12 and op_c * 2 >= n:
                return 'C'
            return 'D'
        if d_streak == 2:
            if op_c * 3 >= n * 2:
                return 'D' if rng.random() < 0.6 else 'C'
            return 'D'
        # single defection: TFT-style punishment but forgive quickly
        if op_c * 4 >= n * 3:
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        if op_c * 3 >= n * 2:
            return 'D'
        return 'D'

    # Opponent cooperated last. Stay cooperative but probe carefully.
    # If opponent is highly cooperative overall, occasionally test them mid-game.
    if op_d * 6 <= n:
        # Very cooperative; probe rarely, avoiding endgame (handled above)
        if n >= 15 and n % 11 == 0 and remaining > 10:
            return 'D'
        return 'C'

    # Opponent is moderately cooperative. Prefer C unless we've been exploited.
    if last_me == 'D' and last_op == 'C':
        return 'C'

    # If we just had prolonged DD and now opponent switches to C, reward it
    if c_streak >= 1 and d_streak == 0:
        if n >= 2 and op[-2] == 'D':
            return 'C'

    # Majority cooperative recent: cooperate
    if recent_c >= recent_d:
        return 'C'

    # Otherwise cooperate by default with slight probing bias
    if op_c * 2 >= n:
        return 'C'
    return 'D'
